import{_ as a}from"./chunks/ark_dist.BU6IWzVh.js";import{_ as r,o as n,c as o,al as i}from"./chunks/framework.7vp1BMOE.js";const m=JSON.parse('{"title":"ARK DIST MR","description":"","frontmatter":{},"headers":[],"relativePath":"uk/dronecan/ark_dist_mr.md","filePath":"uk/dronecan/ark_dist_mr.md"}'),t={name:"uk/dronecan/ark_dist_mr.md"};function l(c,e,d,s,h,_){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="ark-dist-mr" tabindex="-1">ARK DIST MR <a class="header-anchor" href="#ark-dist-mr" aria-label="Permalink to &quot;ARK DIST MR&quot;">​</a></h1><p>ARK DIST MR is a mid range, open source <a href="./">DroneCAN</a> <a href="./../sensor/rangefinders">distance sensor</a>.</p><p><img src="'+a+'" alt="ARK DIST MR"></p><h2 id="де-купити" tabindex="-1">Де купити <a class="header-anchor" href="#де-купити" aria-label="Permalink to &quot;Де купити&quot;">​</a></h2><p>Замовте цей модуль з:</p><ul><li><a href="https://arkelectron.com/product/ark-dist-mr/" target="_blank" rel="noreferrer">ARK Electronics</a> (US)</li></ul><h2 id="характеристики-обладнання" tabindex="-1">Характеристики обладнання <a class="header-anchor" href="#характеристики-обладнання" aria-label="Permalink to &quot;Характеристики обладнання&quot;">​</a></h2><ul><li><a href="https://github.com/ARK-Electronics/ARK_DIST" target="_blank" rel="noreferrer">Open Source Schematic and BOM</a></li><li>Датчики <ul><li><a href="https://www.broadcom.com/products/optical-sensors/time-of-flight-3d-sensors/afbr-s50lx85d" target="_blank" rel="noreferrer">Broadcom AFBR-S50LX85D Time-of-Flight Distance Sensor</a><ul><li>Typical distance range up to 50m</li><li>Інтегроване джерело світла лазера 850 нм</li><li>Поле зору (FoV) 12,4° x 6,2° з 32 пікселями</li><li>Робота в умовах 200 тис. люксів світла навколишнього середовища</li><li>Reference Pixel for system health monitoring</li><li>Добре працює на всіх поверхнях</li><li>Трансмітер пучка 2° x 2° для підсвічування між 1 та 3 пікселями</li></ul></li></ul></li><li>Два роз&#39;єми стандарту CAN для Pixhawk (4 контакти JST GH)</li><li>Pixhawk Standard UART Connector (6 Pin JST SH)</li><li>Роз&#39;єм для відлагодження стандарту Pixhawk (6 контактів JST SH)</li><li>Малий форм-фактор <ul><li>2.0cm x 2.8cm x 1.4cm</li><li>4g</li></ul></li><li>LED індикатори</li><li>USA Built</li><li>NDAA Compliant</li><li>Вимоги до живлення <ul><li>5v <ul><li>78mA Average</li><li>84mA Max</li></ul></li></ul></li></ul><h2 id="налаштування-програмного-забезпечення" tabindex="-1">Налаштування програмного забезпечення <a class="header-anchor" href="#налаштування-програмного-забезпечення" aria-label="Permalink to &quot;Налаштування програмного забезпечення&quot;">​</a></h2><h3 id="підключення" tabindex="-1">Підключення <a class="header-anchor" href="#підключення" aria-label="Permalink to &quot;Підключення&quot;">​</a></h3><p>The ARK DIST is connected to the CAN bus using a Pixhawk standard 4 pin JST GH cable. For more information, refer to the <a href="./../can/#wiring">CAN Wiring</a> instructions.</p><p>The ARK DIST can also be connected with UART and communicates over MAVLink sending the <a href="https://mavlink.io/en/messages/common.html#DISTANCE_SENSOR" target="_blank" rel="noreferrer">DISTANCE_SENSOR</a> message.</p><h2 id="налаштування-прошивки" tabindex="-1">Налаштування прошивки <a class="header-anchor" href="#налаштування-прошивки" aria-label="Permalink to &quot;Налаштування прошивки&quot;">​</a></h2><p>ARK DIST MR runs the <a href="./px4_cannode_fw">PX4 DroneCAN Firmware</a>. As such, it supports firmware update over the CAN bus and <a href="./#node-id-allocation">dynamic node allocation</a>.</p><h2 id="конфігурація-px4" tabindex="-1">Конфігурація PX4 <a class="header-anchor" href="#конфігурація-px4" aria-label="Permalink to &quot;Конфігурація PX4&quot;">​</a></h2><h3 id="dronecan" tabindex="-1">DroneCAN <a class="header-anchor" href="#dronecan" aria-label="Permalink to &quot;DroneCAN&quot;">​</a></h3><h4 id="увімкнути-dronecan" tabindex="-1">Увімкнути DroneCAN <a class="header-anchor" href="#увімкнути-dronecan" aria-label="Permalink to &quot;Увімкнути DroneCAN&quot;">​</a></h4><p>Кроки наступні:</p><ul><li>In <em>QGroundControl</em> set the parameter <a href="./../advanced_config/parameter_reference#UAVCAN_ENABLE">UAVCAN_ENABLE</a> to <code>2</code> for dynamic node allocation (or <code>3</code> if using <a href="./../dronecan/escs">DroneCAN ESCs</a>) and reboot (see <a href="./../advanced_config/parameters">Finding/Updating Parameters</a>).</li><li>Connect ARK DIST SR CAN to the Pixhawk CAN.</li></ul><p>Після активації модуль буде виявлено при завантаженні. Distance sensor data should arrive at 40Hz.</p><p>DroneCAN configuration in PX4 is explained in more detail in <a href="./../dronecan/#enabling-dronecan">DroneCAN &gt; Enabling DroneCAN</a>.</p><h4 id="can-configuration" tabindex="-1">CAN Configuration <a class="header-anchor" href="#can-configuration" aria-label="Permalink to &quot;CAN Configuration&quot;">​</a></h4><p>First set the parameters to <a href="#enable-dronecan">Enable DroneCAN</a> (as shown above).</p><p>Set the following parameters in <em>QGroundControl</em>:</p><ul><li>Enable <a href="./../advanced_config/parameter_reference#UAVCAN_ENABLE">UAVCAN_ENABLE</a> to 2 for dynamic node allocation.</li><li>Enable <a href="./../advanced_config/parameter_reference#UAVCAN_SUB_RNG">UAVCAN_SUB_RNG</a>.</li><li>Set <a href="./../advanced_config/parameter_reference#EKF2_RNG_A_HMAX">EKF2_RNG_A_HMAX</a> to <code>50</code>.</li><li>Set <a href="./../advanced_config/parameter_reference#EKF2_RNG_QLTY_T">EKF2_RNG_QLTY_T</a> to <code>0.2</code>.</li><li>Set <a href="./../advanced_config/parameter_reference#UAVCAN_RNG_MIN">UAVCAN_RNG_MIN</a> to <code>0.08</code>.</li><li>Set <a href="./../advanced_config/parameter_reference#UAVCAN_RNG_MAX">UAVCAN_RNG_MAX</a> to <code>50</code>.</li></ul><p>See also <a href="./../dronecan/#distance-sensor-range-finder">Distance Sensor/Range Finder in <em>DroneCAN &gt; Subscriptions and Publications</em></a>.</p><h3 id="uart-mavlink-configuration" tabindex="-1">UART/MAVLink Configuration <a class="header-anchor" href="#uart-mavlink-configuration" aria-label="Permalink to &quot;UART/MAVLink Configuration&quot;">​</a></h3><p>If connecting via a UART set the following parameters in <em>QGroundControl</em>:</p><ul><li>Set <a href="./../advanced_config/parameter_reference#MAV_0_CONFIG">MAV_X_CONFIG</a> to the port the sensor is connected to.</li><li>Set <a href="./../advanced_config/parameter_reference#MAV_0_FORWARD">MAV_X_FORWARD</a> to <code>0</code> (off).</li><li>Set <a href="./../advanced_config/parameter_reference#MAV_0_MODE">MAV_X_MODE</a> to <code>7</code> or <code>13</code> to (Minimal or Low Bandwidth) to reduce memory usage.</li><li>Set <code>SER_XXX_BAUD</code> to <code>115200</code>, where <code>XXX</code> is specific to the port you are using (such as <a href="./../advanced_config/parameter_reference#SER_GPS2_BAUD">SER_GPS2_BAUD</a>).</li><li>Set <a href="./../advanced_config/parameter_reference#EKF2_RNG_A_HMAX">EKF2_RNG_A_HMAX</a> to <code>50</code>.</li><li>Set <a href="./../advanced_config/parameter_reference#EKF2_RNG_QLTY_T">EKF2_RNG_QLTY_T</a> to <code>0.2</code>.</li></ul><h2 id="дивіться-також" tabindex="-1">Дивіться також <a class="header-anchor" href="#дивіться-також" aria-label="Permalink to &quot;Дивіться також&quot;">​</a></h2><ul><li><a href="https://docs.arkelectron.com/sensor/ark-dist" target="_blank" rel="noreferrer">ARK DIST MR</a> (ARK Docs)</li></ul>',31)])])}const u=r(t,[["render",l]]);export{m as __pageData,u as default};
